sys_script_fix.script:
// ER Triage - Test LLM Connection
// Calls the real LLM once (about 10-20 seconds, a few cents) and prints every schema field.
// Ends with a contract check against ERTriageLLMStub, which is what ERTriageService expects.
// Expected: "Available: true", a differential with condition names only, "CONTRACT PASS".
(function() {
  // Optional: set to an encounter number (e.g. 'ENC0001004') to test with that
  // encounter's real records. Leave empty to use the fixed demo case below.
  var ENCOUNTER_NUMBER = '';

  var DEMO_CASE = [
    'De-identified ED triage case (synthetic data).',
    '',
    'Age: 58 years',
    'Sex: male',
    'Arrival mode: walk-in',
    'Chief complaint: Bad indigestion',
    'Triage note: Epigastric discomfort for 2 hours, sweaty',
    '',
    'Vital signs:',
    '- Heart rate: 108 bpm',
    '- Blood pressure: 150/92 mmHg',
    '- Respiratory rate: 18 breaths/min',
    '- SpO2: 96%',
    '- Temperature: not recorded',
    '- GCS: 15/15',
    '- Pain score: 6/10',
    '- Glucose: not recorded',
    '',
    'Risk flags: diabetic',
    'Medical history: Type 2 diabetes, hypertension',
    'Medications: Metformin, lisinopril',
    'Allergies: no known drug allergies'
  ].join('\n');

  var llm = new ERTriageLLM();
  gs.info('Config: ' + JSON.stringify(llm.describeConfig()));

  var caseText = DEMO_CASE;
  if (ENCOUNTER_NUMBER) {
    var e = new GlideRecord('x_2206627_er_tri_0_encounter');
    if (!e.get('number', ENCOUNTER_NUMBER)) {
      gs.error('Encounter ' + ENCOUNTER_NUMBER + ' not found');
      return;
    }
    var v = new GlideRecord('x_2206627_er_tri_0_vitals');
    v.addQuery('encounter', e.getUniqueValue());
    v.orderByDesc('taken_at');
    v.setLimit(1);
    v.query();
    caseText = new ERTriageCaseBuilder().build(e, v.next() ? v : null);
  }
  gs.info('Case text:\n' + caseText);

  var out = llm.analyze(caseText);
  gs.info('Available: ' + out.available);
  gs.info('Meta: ' + JSON.stringify(out.meta));
  if (!out.available) {
    gs.error('Fallback reason: ' + out.reason);
    return;
  }

  var r = out.result;
  var lines = [
    'Suggested ESI: ' + r.suggested_esi + ' (confidence: ' + r.confidence + ')',
    'Rationale: ' + r.rationale,
    'Symptoms: ' + r.extracted_symptoms.join(' | '),
    'Risk factors: ' + r.risk_factors.join(' | '),
    'Missing information: ' + r.missing_information.join(' | '),
    'Differential:'
  ];
  r.differential.forEach(function(d, i) {
    lines.push('  ' + (i + 1) + '. ' + d.condition + (d.icd10 ? ' (' + d.icd10 + ')' : '') +
      ' | likelihood: ' + d.likelihood + (d.cant_miss ? ' | CAN\'T MISS' : ''));
    lines.push('     + supports: ' + d.supporting.join('; '));
    lines.push('     - against: ' + d.contradicting.join('; '));
    lines.push('     ? ask: ' + d.suggested_questions.join('; '));
    lines.push('     > workup: ' + d.suggested_workup.join('; '));
  });
  if (out.meta.repairs.length) lines.push('Repairs applied: ' + out.meta.repairs.join('; '));
  gs.info('\n' + lines.join('\n'));

  // Contract check: same keys and types as the stub
  function kind(x) {
    if (Array.isArray(x)) return 'array';
    return x === null ? 'null' : typeof x;
  }
  function compare(expected, actual, path, problems) {
    for (var k in expected) {
      if (!(k in actual)) problems.push(path + k + ' is missing');
      else if (kind(expected[k]) != kind(actual[k])) {
        problems.push(path + k + ' is ' + kind(actual[k]) + ', expected ' + kind(expected[k]));
      }
    }
  }
  var stub = new ERTriageLLMStub().analyze('x');
  var problems = [];
  compare(stub, out, '', problems);
  compare(stub.result, r, 'result.', problems);
  r.differential.forEach(function(d, i) {
    compare(stub.result.differential[0], d, 'result.differential[' + i + '].', problems);
  });
  ['model', 'prompt_version', 'latency_ms', 'format_repaired', 'response_id'].forEach(function(k) {
    if (out.meta[k] == null) problems.push('meta.' + k + ' is missing (ERTriageService writes it)');
  });
  r.differential.forEach(function(d, i) {
    if (d.condition.length > 60 || d.condition.indexOf(':') > -1) {
      problems.push('differential[' + i + '].condition looks like it contains reasoning: ' + d.condition);
    }
  });

  if (problems.length) gs.error('CONTRACT FAIL: ' + problems.join('; '));
  else gs.info('CONTRACT PASS: same shape as ERTriageLLMStub; condition fields hold names only');
})();
